# 1. PROFILE: cargo install flamegraph; cargo flamegraph --release
#    (or criterion's built-in flamegraph)
# 3. ONE CHANGE at the measured hotspot. The usual Rust wins:

//    a. layout: stream a struct array rather than chasing pointers
#[derive(Clone, Copy)]
struct P { x: f64, y: f64 }
fn sum(ps: &[P]) -> f64 {           // contiguous: one cache line serves several
    ps.iter().map(|p| p.x + p.y).sum()
}

//    b. bounds-check elimination: iterate, don't index
fn at(xs: &[i32], i: usize) -> i32 {
    // xs[i] keeps a bounds check; an iterator lets LLVM prove it
    xs.get(i).copied().unwrap_or(0)
}

//    c. cache-line padding for a concurrent counter (the ping-pong this fixes)
#[repr(align(64))]
struct PaddedCounter(std::sync::atomic::AtomicU64);

// 4. VERIFY with criterion: it reports a confidence interval, so a change
//    inside the noise is visible as such.
//    [[bench]] name = "sum"; harness = false
// 5. GUARD: keep the criterion bench in CI (cargo bench -- --save-baseline).
// TRAP: -C target-cpu=native changes what LLVM decides - the benchmark's
